(()=>{'use strict';const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));const old=window.render;function activate(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(id)?.classList.add('active');document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'});try{window.lucide?.createIcons()}catch{}}function page(k,t,d,body){const h=document.getElementById('more');h.innerHTML=`<div class="public-page premium-page"><button class="back-home" data-view="home">← Kembali ke Beranda</button><div class="public-head"><span class="eyebrow">${esc(k)}</span><h2>${esc(t)}</h2><p>${esc(d)}</p></div>${body}</div>`;activate('more');h.querySelector('[data-view=home]').onclick=()=>window.render('home')}function about(){page('TENTANG KAMI','WASKITA — Indonesia Punya Masalah','Ruang publik untuk melihat, memahami, dan mengantisipasi persoalan di sekitar kita.',`<div class="about-hero visual-card"><div class="about-icon">◎</div><div><h3>Untuk publik, dengan informasi yang lebih mudah dipahami.</h3><p>WASKITA dirancang sebagai pintu masuk informasi publik: warga dapat menemukan masalah, menelusuri wilayah, membaca data yang tersedia, menyampaikan laporan, dan mengikuti perubahan dari waktu ke waktu.</p></div></div><div class="info-grid premium-grid"><article class="info-card"><span class="feature-icon">◈</span><b>Lihat</b><p>Temukan masalah dan informasi publik melalui bidang, pencarian, serta peta wilayah.</p></article><article class="info-card"><span class="feature-icon">◇</span><b>Pahami</b><p>Baca konteks, status, waktu pembaruan, dan informasi pendukung yang tersedia.</p></article><article class="info-card"><span class="feature-icon">△</span><b>Antisipasi</b><p>Pantau perubahan dan sampaikan informasi baru melalui kanal Suara Warga.</p></article></div><div class="visual-card about-principles"><h3>Prinsip WASKITA</h3><div class="principle-grid"><div><b>Transparan</b><span>Sumber dan status informasi dijelaskan seperlunya.</span></div><div><b>Terpisah</b><span>Laporan warga dibedakan dari informasi yang telah diverifikasi.</span></div><div><b>Terukur</b><span>Perubahan ditampilkan berdasarkan data yang tersedia.</span></div><div><b>Nyaman</b><span>Informasi dibuat mudah dibaca di desktop maupun perangkat seluler.</span></div></div></div>`)}function info(view,k,t,d,cards){const h=document.getElementById(view);h.innerHTML=`<div class="public-page premium-page"><button class="back-home" data-view="home">← Kembali ke Beranda</button><div class="public-head"><span class="eyebrow">${esc(k)}</span><h2>${esc(t)}</h2><p>${esc(d)}</p></div><div class="premium-service-grid">${cards.map(c=>`<article class="visual-card service-card"><div class="service-icon">${c.i}</div><div><h3>${esc(c.t)}</h3><p>${esc(c.d)}</p></div><button class="btn-outline" data-view="${c.v||'problems'}">Buka →</button></article>`).join('')}</div></div>`;activate(view);h.querySelector('[data-view=home]').onclick=()=>window.render('home');h.querySelectorAll('[data-view]:not([data-view=home])').forEach(b=>b.onclick=()=>window.render(b.dataset.view))}window.render=async function(v,x=''){if(v==='more'){about();return}if(v==='monitoring'){info('monitoring','PANTAU PERUBAHAN','Pantau perubahan informasi publik secara sederhana dan jelas.','Ikuti status, waktu pembaruan, dan informasi terkait dari masalah yang sudah tercatat.',[{i:'↗',t:'Pembaruan status',d:'Lihat status terbaru pada detail masalah publik.',v:'problems'},{i:'◷',t:'Waktu perubahan',d:'Perhatikan tanggal pembaruan untuk memahami perkembangan informasi.',v:'problems'},{i:'⌁',t:'Tanggapan warga',d:'Sampaikan informasi terkait melalui Suara Warga.',v:'report'}]);return}if(v==='solutions'){info('solutions','RUANG SOLUSI','Ruang publik untuk memahami pilihan tindak lanjut.','Gunakan informasi yang tersedia untuk memahami persoalan dan mengarahkan tindak lanjut secara bertanggung jawab.',[{i:'◈',t:'Kenali persoalan',d:'Mulai dari bidang, lokasi, status, dan informasi yang tersedia.',v:'problems'},{i:'✦',t:'Tambahkan informasi',d:'Warga dapat mengirim laporan, foto, dan video pendukung.',v:'report'},{i:'◎',t:'Pantau perkembangan',d:'Kembali ke masalah dan lihat pembaruan yang tersedia.',v:'monitoring'}]);return}return typeof old==='function'?old(v,x):undefined};document.addEventListener('DOMContentLoaded',()=>{try{window.lucide?.createIcons()}catch{}})})();